mapper.select:
SELECT s.id FROM sys_steel_classification s LEFT JOIN sys_steel_classification_match sm ON sm.steel_id = s.id and sm.bool_delete_enum = 0 LEFT JOIN sys_steel_classify_link sc ON sc.steel_id = s.id and sc.bool_delete_enum = 0 LEFT JOIN sys_steel_class_spec_name_link matchName ON matchName.steel_id = s.id and matchName.bool_delete_enum = 0 where s.bool_delete_enum = 0
and s.product_classification_enum = #{productClassificationEnum}
and s.mes_product_enum = #{mesProductEnum}
and (s.name like concat('%',#{sectionAndNameAndType},'%') or sm.keyword like concat('%',#{sectionAndNameAndType},'%'))
